CREATE TABLE IF NOT EXISTS tabor_infra_jobs (job_id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,job_type TEXT NOT NULL CHECK(job_type IN ('inventory-audit','genesis-selftest','telemetry-check')),payload_json TEXT NOT NULL DEFAULT '{}',state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','claimed','completed','failed')),created_at TEXT DEFAULT CURRENT_TIMESTAMP,claimed_at TEXT,completed_at TEXT,receipt_json TEXT);CREATE INDEX IF NOT EXISTS tabor_infra_jobs_state ON tabor_infra_jobs(state,created_at);